CustomField.formula:
'RV-'&Unit__r.Project__r.Voucher_Code__c&'-'&
IF(Unit__r.Project_Name_F__c == 'MIRA Villas Designed by Bentley Home',
  TEXT(Voucher_Number_To_Process_Bentley__c),
  IF(Unit__r.Project_Name_F__c == 'Trussardi Residences',
    TEXT(Voucher_Number_To_Process_Trussardi__c),
    IF(Unit__r.Project_Name_F__c == 'Trussardi Residences 2',
      TEXT(Voucher_Number_To_Process_Trussardi2__c),
      IF(Unit__r.Project_Name_F__c == 'GIANFRANCO FERRE RESIDENCES',
        TEXT(Voucher_Number_To_Process_Gianfranco__c),
        IF(Unit__r.Project_Name_F__c == 'Trussardi Residences 2 Offices',
          TEXT(Voucher_Number_To_Process_T2_Offices__c),
          IF(Unit__r.Project_Name_F__c == 'John Richmond Residences',
            TEXT(Voucher_Number_To_Process_Richmond__c),
            IF(Unit__r.Project_Name_F__c == 'Trussardi Residences MIRA VERDE',
              TEXT(Voucher_Number_To_Process_MIRA_VERDE__c),
              TEXT(Voucher_Number_To_Process_POST__c)
            )
          )
        )
      )
    )
  )
)
